function round(num, digits = 3) {
  return Number(num.toFixed(digits));
}

function median(arr) {
  if (!arr.length) return null;
  const sorted = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2
    ? sorted[mid]
    : (sorted[mid - 1] + sorted[mid]) / 2;
}

const oddsData = $('Get NBA Odds').all();

const games = oddsData
  .map(item => item.json)
  .filter(game => Array.isArray(game.bookmakers) && game.bookmakers.length > 0)
  .map(game => {
    const homeOdds = [];
    const awayOdds = [];
    const homeSpreads = [];
    const awaySpreads = [];
    const totals = [];

    for (const bm of game.bookmakers) {
      if (!Array.isArray(bm.markets)) continue;

      const h2h = bm.markets.find(m => m.key === 'h2h');
      if (h2h?.outcomes) {
        for (const outcome of h2h.outcomes) {
          if (outcome.name === game.home_team) homeOdds.push(outcome.price);
          if (outcome.name === game.away_team) awayOdds.push(outcome.price);
        }
      }

      const spreads = bm.markets.find(m => m.key === 'spreads');
      if (spreads?.outcomes) {
        for (const outcome of spreads.outcomes) {
          if (outcome.name === game.home_team && outcome.point != null) {
            homeSpreads.push(outcome.point);
          }
          if (outcome.name === game.away_team && outcome.point != null) {
            awaySpreads.push(outcome.point);
          }
        }
      }

      const totalsMarket = bm.markets.find(m => m.key === 'totals');
      if (totalsMarket?.outcomes) {
        for (const outcome of totalsMarket.outcomes) {
          if (outcome.point != null) totals.push(outcome.point);
        }
      }
    }

    if (!homeOdds.length || !awayOdds.length) return null;

    const avgHomeOdds = homeOdds.reduce((a, b) => a + b, 0) / homeOdds.length;
    const avgAwayOdds = awayOdds.reduce((a, b) => a + b, 0) / awayOdds.length;

    const rawHome = 1 / avgHomeOdds;
    const rawAway = 1 / avgAwayOdds;
    const overround = rawHome + rawAway;

    const noVigHomeProb = rawHome / overround;
    const noVigAwayProb = rawAway / overround;

    return {
      game_id: game.id,
      commence_time: game.commence_time,
      home_team: game.home_team,
      away_team: game.away_team,

      avg_home_odds: round(avgHomeOdds, 2),
      avg_away_odds: round(avgAwayOdds, 2),

      best_home_odds: round(Math.max(...homeOdds), 2),
      best_away_odds: round(Math.max(...awayOdds), 2),

      median_home_odds: round(median(homeOdds), 2),
      median_away_odds: round(median(awayOdds), 2),

      market_home_prob_novig: round(noVigHomeProb, 4),
      market_away_prob_novig: round(noVigAwayProb, 4),

      avg_home_spread: homeSpreads.length
        ? round(homeSpreads.reduce((a, b) => a + b, 0) / homeSpreads.length, 2)
        : null,

      avg_away_spread: awaySpreads.length
        ? round(awaySpreads.reduce((a, b) => a + b, 0) / awaySpreads.length, 2)
        : null,

      avg_total: totals.length
        ? round(totals.reduce((a, b) => a + b, 0) / totals.length, 2)
        : null,

      bookmaker_count: game.bookmakers.length
    };
  })
  .filter(Boolean);

return games.map(game => ({ json: game }));

