// ─────────────────────────────────────────────────────────────────────
// Hilfsfunktionen
// ─────────────────────────────────────────────────────────────────────

// Streak-Label mit Emoji:
// "W4" → " 🔥W4" (Gewinnstreak)
// "L3" → " ❄️L3" (Verlustserie)
function streakLabel(streak) {
  if (!streak) return '';
  return streak.startsWith('W') ? ` 🔥${streak}` : ` ❄️${streak}`;
}

// Momentum der letzten 2 Spiele als Pfeil-Emoji:
// "2/2" (beide gewonnen) → ⬆️, "0/2" (beide verloren) → ⬇️
function momentumLabel(momentum) {
  if (momentum === '2/2') return ' ⬆️';
  if (momentum === '0/2') return ' ⬇️';
  return '';  // "1/2" = neutral, kein Symbol
}

// Head-to-Head Zeile formatieren
// avg_game_total ist neu in der API — zeigt den historischen Schnitt der Spielsumme
function h2hLine(h2h, homeTeam, awayTeam) {
  if (!h2h || !h2h.available) return 'H2H: Keine Daten';
  const diff = h2h.avg_point_diff > 0
    ? `+${h2h.avg_point_diff} ${homeTeam}`
    : `+${Math.abs(h2h.avg_point_diff)} ${awayTeam}`;
  const totalStr = h2h.avg_game_total ? ` | H2H Total: ${h2h.avg_game_total}` : '';
  return `H2H: ${homeTeam} ${h2h.home_team_wins}-${h2h.away_team_wins} ${awayTeam} | Ø ${diff}${totalStr}`;
}

// Konfidenz → farbiges Kreissymbol
// Telegram unterstützt keine Farben, aber diese Unicode-Kreise sind lesbar
function confidenceEmoji(confidence) {
  if (confidence === 'Hoch')   return '🟢';
  if (confidence === 'Mittel') return '🟡';
  return '🔴';
}

// Verletzungsprofil als kompakte Inline-Zusammenfassung
// Zeigt nur Dimensionen mit Impact > 3 (sonst zu viel Lärm)
// Beispiel: " [Off 5.2 | PG 4.1 | Rim 7.3]"
function injuryProfileLine(profile) {
  if (!profile) return '';
  const parts = [];
  if ((profile.offense_impact        || 0) > 3) parts.push(`Off ${Number(profile.offense_impact).toFixed(1)}`);
  if ((profile.defense_impact        || 0) > 3) parts.push(`Def ${Number(profile.defense_impact).toFixed(1)}`);
  if ((profile.playmaking_impact     || 0) > 3) parts.push(`PG ${Number(profile.playmaking_impact).toFixed(1)}`);
  if ((profile.shooting_impact       || 0) > 3) parts.push(`Shoot ${Number(profile.shooting_impact).toFixed(1)}`);
  if ((profile.rim_protection_impact || 0) > 3) parts.push(`Rim ${Number(profile.rim_protection_impact).toFixed(1)}`);
  return parts.length > 0 ? ` [${parts.join(' | ')}]` : '';
}

// ─────────────────────────────────────────────────────────────────────
// Hauptlogik
// ─────────────────────────────────────────────────────────────────────

// $input.all() = alle Items die von AI Agent kommen (1 pro Spiel)
// $('If').all() = alle Items die durch den If-Filter kamen (selbe Reihenfolge!)
// Wichtig: beide Arrays haben gleiche Länge und gleiche Reihenfolge,
// weil AI Agent pro Input-Item genau ein Output-Item erzeugt.
const allOutputs = $input.all();
const ifItems    = $('If').all();

const blocks = [];  // Sammlung aller Nachrichten-Blöcke

allOutputs.forEach((item, index) => {
  const aiOutput = item.json.output || '';

  // gameData enthält alle berechneten Felder (Stats, Injuries, Features etc.)
  // Wir holen sie aus dem If-Node, weil der AI Agent diese Felder strippt
  // (AI Agent gibt nur { output: "..." } zurück, nicht die Eingangsdaten)
  const gameData = ifItems[index]?.json || {};
  const hs   = gameData.home_stats || {};
  const as_  = gameData.away_stats || {};
  const fb   = gameData.feature_breakdown || {};
  const mc   = gameData.market_correction || {};
  const tp   = gameData.totals_pick || {};
  const homeTeam  = gameData.home_team || '';
  const awayTeam  = gameData.away_team || '';
  const conf      = gameData.confidence || '';
  const homeInj   = gameData.home_injuries_structured || {};
  const awayInj   = gameData.away_injuries_structured || {};

  // Prüfe ob ML-Pick empfohlen wurde
  const hasMLPick     = aiOutput.includes('JA SETZEN');

  // Prüfe ob ein guter Totals-Pick vorliegt
  // (direction = "Over"/"Under", Confidence nicht "Niedrig")
  const hasTotalsPick = tp.direction && tp.confidence !== 'Niedrig';

  // Weder ML noch Totals → dieses Spiel komplett überspringen
  if (!hasMLPick && !hasTotalsPick) return;

  let block = '';

  if (hasMLPick) {
    // ── Fall 1: ML-Pick vorhanden ──────────────────────────────────
    // AI-Text aufbereiten: Schlüsselwörter durch fettgedruckte Markdown-Versionen ersetzen
    // Telegram unterstützt *fett* und _kursiv_ im MarkdownV2-Modus
    const confEmoji = confidenceEmoji(conf);
    let aiText = aiOutput
      .replace('SPIEL:',       '🏟 *SPIEL:*')
      .replace('TIPP:',        '✅ *TIPP:*')
      .replace('QUOTE:',       '💰 *QUOTE:*')
      .replace(/KONFIDENZ: (\S+)/, `📊 *KONFIDENZ:* ${confEmoji} $1`)
      .replace('BEGRÜNDUNG:',  '📝 *BEGRÜNDUNG:*')
      .replace('EMPFEHLUNG:',  '🎯 *EMPFEHLUNG:*');

    block = aiText;
  } else {
    // ── Fall 2: Nur Totals-Pick (ML war SKIP) ─────────────────────
    // Wir zeigen einen eigenen Header, kein AI-Text
    block = `🏟 *SPIEL:* ${homeTeam} vs ${awayTeam}\n`;
    block += `📊 *NUR TOTALS-PICK* (Moneyline kein Value)`;
  }

  // ── Form & Fatigue (immer anzeigen) ───────────────────────────────
  // rest_days = Tage seit letztem Spiel → 1 = gestern gespielt (B2B-Risiko)
  block += `\n\n📈 *Form (letzte 10 | letzte 2):*`;
  block += `\n  ${homeTeam}: ${hs.last_10_record || 'N/A'}${streakLabel(hs.streak)}${momentumLabel(fb.home_momentum)}${hs.back_to_back ? ' ⚠️B2B' : ''} | Rest: ${hs.rest_days ?? '?'}T`;
  block += `\n  ${awayTeam}: ${as_.last_10_record || 'N/A'}${streakLabel(as_.streak)}${momentumLabel(fb.away_momentum)}${as_.back_to_back ? ' ⚠️B2B' : ''} | Rest: ${as_.rest_days ?? '?'}T`;
  block += `\n🤝 ${h2hLine(gameData.h2h, homeTeam, awayTeam)}`;

  // ── Net-Rating-Differenz ───────────────────────────────────────────
  // net_pts_diff = (eigene PPG) - (Gegner-PPG der letzten 10 Spiele)
  // positiver Wert = mehr Punkte erzielt als kassiert → gute Offensiv/Defensivbilanz
  if (hs.net_pts_diff !== undefined || as_.net_pts_diff !== undefined) {
    const hNet = hs.net_pts_diff;
    const aNet = as_.net_pts_diff;
    block += `\n📊 *Net-Δ:* ${homeTeam} ${hNet > 0 ? '+' : ''}${hNet} | ${awayTeam} ${aNet > 0 ? '+' : ''}${aNet}`;
  }

  // ── Verletzungsprofil ──────────────────────────────────────────────
  // Nur anzeigen wenn mindestens ein Team betroffen ist (Score > 0)
  const homeInjScore = homeInj.injury_impact_score || 0;
  const awayInjScore = awayInj.injury_impact_score || 0;
  if (homeInjScore > 0 || awayInjScore > 0) {
    const homeProfileStr = injuryProfileLine(homeInj.injury_profile);
    const awayProfileStr = injuryProfileLine(awayInj.injury_profile);
    const homeAbs = (homeInj.key_absences || []).join(', ') || 'keine';
    const awayAbs = (awayInj.key_absences || []).join(', ') || 'keine';
    block += `\n🏥 *Verletzungen:*`;
    block += `\n  ${homeTeam}: ${homeInjScore}${homeProfileStr} | ${homeAbs}`;
    block += `\n  ${awayTeam}: ${awayInjScore}${awayProfileStr} | ${awayAbs}`;
  }

  // ── Markt-Korrektur-Info (nur bei ML-Pick relevant) ───────────────
  // clamped_edge = tatsächliche Abweichung vom Markt nach Clamping
  // Wenn raw_edge ≠ clamped_edge: Modell wollte stärker abweichen, wurde aber begrenzt
  if (hasMLPick && mc.clamped_edge !== undefined) {
    const wasClipped = mc.raw_edge !== mc.clamped_edge;
    const clampInfo  = wasClipped
      ? ` (geclampt von ${(mc.raw_edge * 100).toFixed(1)}%)`
      : '';
    block += `\n📐 *Markt-Korrektur:* ${(mc.clamped_edge * 100).toFixed(1)}%${clampInfo} | max ±${(mc.max_deviation * 100).toFixed(0)}%`;
  }

  // ── Totals-Pick ────────────────────────────────────────────────────
  // signal_strength = Differenz zwischen erwartetem und Markt-Total in Punkten
  // reasons = Liste der Faktoren die das Signal treiben (z.B. "Shooters out -2.1")
  if (hasTotalsPick) {
    const totalsEmoji  = tp.direction === 'Over' ? '📈' : '📉';
    const reasonsStr   = (tp.reasons || []).length > 0
      ? ` | ${tp.reasons.join(', ')}`
      : '';
    block += `\n\n${totalsEmoji} *Totals:* ${tp.direction} ${tp.line}`;
    block += ` | Erwartet: ${tp.expected}${reasonsStr}`;
    block += ` | ${confidenceEmoji(tp.confidence)} ${tp.confidence}`;
  }

  blocks.push(block);
});

// ── Abschlussnachricht ─────────────────────────────────────────────
// Wenn blocks leer ist: keine einzige Empfehlung heute
if (blocks.length === 0) {
  return [{ json: { message: '🏀 NBA Analyse heute\n\nKeine Value Bets mit ausreichender Konfidenz gefunden. ✋' } }];
}

// Alle Blöcke mit Trennlinie zusammensetzen
let message = `🏀 *NBA VALUE BETS – ${new Date().toLocaleDateString('de-DE')}*\n`;
message += '━━━━━━━━━━━━━━━━\n\n';
message += blocks.join('\n\n━━━━━━━━━━━━━━━━\n\n');

return [{ json: { message } }];

