  'Out': 1.0, 'Doubtful': 0.85, 'Questionable': 0.5,
  'Probable': 0.2, 'Day-To-Day': 0.6
};

function getPosition(name) {
  if (POSITION_MAP[name]) return POSITION_MAP[name];
  const pd = playerData[name];
  if (pd && pd.position) return pd.position;
  return 'UNKNOWN';
}

function getBaseWeight(name) {
  let base = STAR_WEIGHTS[name] || 4;
  const pd = playerData[name];
  if (pd && pd.net_rating > 5.0) base = Math.max(base, 8);
  return base;
}

function getCommentMultiplier(comment) {
  if (!comment) return 1.0;
  const c = comment.toLowerCase();
  if (c.includes('season') || c.includes('indefinitely') || c.includes('torn')) return 1.0;
  if (c.includes('back-to-back') || c.includes('rest')) return 0.4;
  if (c.includes('not expected') || c.includes('ruled out')) return 1.0;
  if (c.includes('progressing') || c.includes('improving') || c.includes('expected to play')) return 0.3;
  if (c.includes('limited') || c.includes('restricted')) return 0.7;
  return 1.0;
}

const teams = injuryData.injuries || [];
const result = [];

for (const team of teams) {
  const teamName = team.team?.displayName || team.team?.name || 'Unknown';
  const injuries = team.injuries || [];
  const teamPlayers = [];
  let totalImpact = 0;
  const keyAbsences = [];

  // Multi-dimensional injury profile
  let offenseImpact = 0;
  let defenseImpact = 0;
  let shootingImpact = 0;
  let playmakingImpact = 0;
  let rimProtectionImpact = 0;
  let reboundingImpact = 0;

  const starAbsences = [];
  const starterAbsences = [];
  const rotationAbsences = [];
  const shootingAbsencesList = [];
  const rimProtectorAbsencesList = [];

  // Position cluster tracking (Out + Doubtful only)
  const positionCounts = { PG: 0, SG: 0, SF: 0, PF: 0, C: 0 };

  for (const injury of injuries) {
    const name = injury.athlete?.displayName || injury.athlete?.shortName || '';
    const status = injury.status || 'Questionable';
    const shortComment = injury.shortComment || injury.comment || '';
    const baseWeight = getBaseWeight(name);
    const statusMult = STATUS_MULTIPLIER[status] || 0.3;
    const commentMult = getCommentMultiplier(shortComment);
    const pd = playerData[name] || null;

    const impact = Number((baseWeight * statusMult * commentMult).toFixed(2));
    const position = getPosition(name);
    const isHardOut = ['Out', 'Doubtful'].includes(status);
    const isQuestionable = status === 'Questionable' || status === 'Day-To-Day';

    // Cluster tracking (only hard outs)
    if (isHardOut && positionCounts[position] !== undefined) {
      positionCounts[position]++;
    }

    // Role-based dimensional impact (Out + Doubtful + Questionable)
    if (isHardOut || isQuestionable) {
      const dimWeight = isHardOut ? 1.0 : 0.5;

      if (['PG', 'SG', 'SF'].includes(position)) {
        offenseImpact += impact * dimWeight;
      }
      if (DEFENSIVE_ANCHORS.has(name)) {
        defenseImpact += impact * dimWeight * 1.5;
      }
      if (['SG', 'SF'].includes(position)) {
        shootingImpact += impact * dimWeight;
        if (isHardOut) shootingAbsencesList.push(name);
      }
      if (position === 'PG') {
        playmakingImpact += impact * dimWeight;
      }
      if (RIM_PROTECTORS.has(name)) {
        rimProtectionImpact += impact * dimWeight;
        if (isHardOut) rimProtectorAbsencesList.push(name);
      }
      if (['C', 'PF'].includes(position)) {
        reboundingImpact += impact * dimWeight;
      }
    }

    // Total impact (for backward compat + overall score)
    if (isHardOut) {
      totalImpact += impact;
      if (baseWeight >= 7) keyAbsences.push(name);
      // Absence classification
      if (baseWeight >= 9) starAbsences.push(name);
      else if (baseWeight >= 7) starterAbsences.push(name);
      else rotationAbsences.push(name);
    } else if (isQuestionable) {
      totalImpact += impact * 0.5;
    } else if (status === 'Probable') {
      totalImpact += impact * 0.15;
    }

    const age = pd ? currentYear - pd.birth_year : null;
    teamPlayers.push({
      name, status, position,
      base_weight: baseWeight,
      status_multiplier: statusMult,
      comment_multiplier: commentMult,
      impact,
      shortComment: shortComment ? true : false,
      age,
      birth_year: pd?.birth_year || null,
      net_rating: pd?.net_rating || null
    });
  }

  // Cluster detection
  let clusterMultiplier = 1.0;
  let clusterDetected = false;
  let clusterType = null;
  for (const [pos, count] of Object.entries(positionCounts)) {
    if (count >= 3) {
      clusterMultiplier = Math.max(clusterMultiplier, 1.30);
      clusterDetected = true;
      clusterType = `${pos}_cluster_major`;
    } else if (count >= 2) {
      clusterMultiplier = Math.max(clusterMultiplier, 1.15);
      if (!clusterDetected) { clusterDetected = true; clusterType = `${pos}_cluster`; }
    }
  }

  // Playmaker bonus (alle PGs out)
  const playmakingBonus = positionCounts['PG'] >= 2 ? 5.0 : 0;

  // Depth multiplier
  const depthMult = TEAM_DEPTH[teamName] || 1.0;

  const finalScore = Number((totalImpact * clusterMultiplier * depthMult + playmakingBonus).toFixed(2));

  result.push({
    json: {
      team_name: teamName,
      injury_data: {
        injury_impact_score: finalScore,
        total_injuries: injuries.length,
        out_count: teamPlayers.filter(p => p.status === 'Out').length,
        questionable_count: teamPlayers.filter(p => p.status === 'Questionable').length,
        doubtful_count: teamPlayers.filter(p => p.status === 'Doubtful').length,
        probable_count: teamPlayers.filter(p => p.status === 'Probable').length,
        key_absences: keyAbsences,
        players: teamPlayers,
        cluster_detected: clusterDetected,
        cluster_type: clusterType,
        cluster_multiplier: clusterMultiplier,
        playmaker_bonus: playmakingBonus,
        depth_multiplier: depthMult,
        injury_profile: {
          offense_impact:       Number(offenseImpact.toFixed(2)),
          defense_impact:       Number(defenseImpact.toFixed(2)),
          shooting_impact:      Number(shootingImpact.toFixed(2)),
          playmaking_impact:    Number(playmakingImpact.toFixed(2)),
          rim_protection_impact: Number(rimProtectionImpact.toFixed(2)),
          rebounding_impact:    Number(reboundingImpact.toFixed(2))
        },
        star_absences:             starAbsences,
        starter_absences:          starterAbsences,
        rotation_absences:         rotationAbsences,
        shooting_absences:         shootingAbsencesList,
        rim_protector_absences:    rimProtectorAbsencesList,
        position_cluster:          positionCounts
      }
    }
  });
}

return result;

