// B2B: Questionable 0.5→0.85, Probable 0.15→0.4 + Alters-Faktor (>32J = x1.2)
const currentYear = new Date().getFullYear();
function applyB2BMultiplier(injuryData, isB2B) {
  if (!isB2B || !injuryData) return injuryData;
  const b2bStatusMap = { 'Questionable': 0.85, 'Probable': 0.4, 'Day-To-Day': 0.55 };
  const adjustedPlayers = (injuryData.players || []).map(p => {
    const newMulti = b2bStatusMap[p.status] || p.status_multiplier;
    let newImpact = Number((p.base_weight * newMulti).toFixed(2));
    // Alters-Faktor: Spieler über 32 → x1.2 bei B2B
    const age = p.age || (currentYear - (p.birth_year || currentYear));
    if (age > 32) newImpact = Number((newImpact * 1.2).toFixed(2));
    return { ...p, status_multiplier: newMulti, impact: newImpact, b2b_adjusted: true, age_factor_applied: age > 32 };
  });
  const rawImpact = adjustedPlayers.reduce((s, p) => s + p.impact, 0);
  const newScore  = Number((rawImpact * (injuryData.cluster_multiplier || 1.0) * (injuryData.depth_multiplier || 1.0) + (injuryData.playmaker_bonus || 0)).toFixed(2));
  return { ...injuryData, players: adjustedPlayers, injury_impact_score: newScore, b2b_adjusted: true };
}

