function clamp(num, min, max) {
  return Math.max(min, Math.min(max, num));
}

function parseRecord(record) {
  if (!record || typeof record !== 'string' || !record.includes('-')) return 0.5;
  const [w, l] = record.split('-').map(Number);
  const total = w + l;
  return total > 0 ? w / total : 0.5;
}

return $input.all().map(item => {
  const j = item.json;

  const home = j.home_stats || {};
  const away = j.away_stats || {};
  const homeProf = j.home_injuries_structured?.injury_profile || {};
  const awayProf = j.away_injuries_structured?.injury_profile || {};

  const homeForm = parseRecord(home.last_10_record);
  const awayForm = parseRecord(away.last_10_record);

  const homeFG = Number(home.avg_fg_pct || 0);
  const awayFG = Number(away.avg_fg_pct || 0);
  const fgDiff = homeFG - awayFG;
  const fgEdge = Math.abs(fgDiff) >= 3 ? fgDiff * 0.003 : 0;

  const homeInjury = Number(j.home_injuries_structured?.injury_impact_score || 0);
  const awayInjury = Number(j.away_injuries_structured?.injury_impact_score || 0);
  const injuryGap  = Math.abs(homeInjury - awayInjury);
  const injuryEdge = (awayInjury - homeInjury) * 0.015;

  const formEdge = (homeForm - awayForm) * 0.10;

  // Momentum: letzte 2 Spiele
  const homeLast2 = (home.recent_games || []).slice(0, 2);
  const awayLast2 = (away.recent_games || []).slice(0, 2);
  const homeMomentum = homeLast2.filter(g => g.wl === 'W').length;
  const awayMomentum = awayLast2.filter(g => g.wl === 'W').length;
  const momentumEdge = ((homeMomentum - awayMomentum) / 2) * 0.02;

  // Streak-Edge
  const homeStreak    = home.streak || '';
  const awayStreak    = away.streak || '';
  const homeStreakType = homeStreak[0];
  const homeStreakLen  = parseInt(homeStreak.slice(1)) || 0;
  const awayStreakType = awayStreak[0];
  const awayStreakLen  = parseInt(awayStreak.slice(1)) || 0;
  let streakEdge = 0;
  if (homeStreakType === 'W' && homeStreakLen >= 3) streakEdge += 0.02;
  if (homeStreakType === 'L' && homeStreakLen >= 3) streakEdge -= 0.02;
  if (awayStreakType === 'W' && awayStreakLen >= 3) streakEdge -= 0.02;
  if (awayStreakType === 'L' && awayStreakLen >= 3) streakEdge += 0.02;

  // B2B-Edge
  const homeB2B = home.back_to_back || false;
  const awayB2B = away.back_to_back || false;
  let b2bEdge = 0;
  if (homeB2B) b2bEdge -= 0.04;
  if (awayB2B) b2bEdge += 0.04;

  // H2H-Edge
  let h2hEdge = 0;
  const h2h = j.h2h;
  if (h2h && h2h.available && h2h.games_found >= 3) {
    h2hEdge = (h2h.home_win_pct - 0.5) * 0.06;
  }

  // Net-Rating Edge (PPG differential from stats API)
  const homeNetPts = Number(home.net_pts_diff || 0);
  const awayNetPts = Number(away.net_pts_diff || 0);
  const netRatingEdge = clamp((homeNetPts - awayNetPts) * 0.003, -0.02, 0.02);

  const marketBase = Number(j.market_home_prob_novig || 0.5);

  // ======== MARKET CORRECTION CLAMPING (Punkt 2) ========
  // Max ±6% normal, ±12% mit starken Faktoren
  const hasStrongFactor =
    injuryGap > 8 ||
    homeB2B || awayB2B ||
    Math.abs(h2hEdge) > 0.02 ||
    Math.abs(homeNetPts - awayNetPts) > 5;

  const maxDeviation = hasStrongFactor ? 0.12 : 0.06;

  const rawEdge = formEdge + fgEdge + injuryEdge + streakEdge + b2bEdge + h2hEdge + momentumEdge + netRatingEdge;
  const clampedEdge = clamp(rawEdge, -maxDeviation, maxDeviation);

  let modelHomeProb = clamp(marketBase + clampedEdge, 0.15, 0.85);
  const modelAwayProb = 1 - modelHomeProb;

  const bestHomeOdds = Number(j.best_home_odds || 0);
  const bestAwayOdds = Number(j.best_away_odds || 0);

  const evHome = bestHomeOdds ? modelHomeProb * bestHomeOdds - 1 : -1;
  const evAway = bestAwayOdds ? modelAwayProb * bestAwayOdds - 1 : -1;

  let valueSide = "SKIP";
  let valueEV   = 0;
  let valueOdds = null;

  if (evHome > evAway && evHome > 0.05) {
    valueSide = j.home_team; valueEV = evHome; valueOdds = bestHomeOdds;
  } else if (evAway > evHome && evAway > 0.05) {
    valueSide = j.away_team; valueEV = evAway; valueOdds = bestAwayOdds;
  }

  // ======== TOTALS ANALYSIS (Punkt 6) ========
  const avgTotal   = Number(j.avg_total || 0);
  const homePPG    = Number(home.avg_pts     || 110);
  const awayPPG    = Number(away.avg_pts     || 110);
  const homeOppPPG = Number(home.avg_opp_pts || homePPG);
  const awayOppPPG = Number(away.avg_opp_pts || awayPPG);

  // Expected total: blended attack/defense matchup
  const homeExpected = (homePPG + awayOppPPG) / 2;
  const awayExpected = (awayPPG + homeOppPPG) / 2;
  const baseExpected = homeExpected + awayExpected;

  // Shooter out → Under
  const homeShootingOut = Number(homeProf.shooting_impact || 0);
  const awayShootingOut = Number(awayProf.shooting_impact || 0);
  const shootingUnder = (homeShootingOut + awayShootingOut) * 0.40;

  // Rim protector out → Over (easier to score)
  const homeRimOut = Number(homeProf.rim_protection_impact || 0);
  const awayRimOut = Number(awayProf.rim_protection_impact || 0);
  const rimOver = (homeRimOut + awayRimOut) * 0.30;

  // B2B → Under (fatigue, slower pace)
  const b2bUnder = (homeB2B ? 2.5 : 0) + (awayB2B ? 2.5 : 0);

  // Short rest → Under
  const homeRest = Number(home.rest_days || 2);
  const awayRest = Number(away.rest_days || 2);
  const restUnder = (homeRest <= 1 ? 1.5 : 0) + (awayRest <= 1 ? 1.5 : 0);

  // Playmaking out → Under (fewer good looks)
  const homePMOut = Number(homeProf.playmaking_impact || 0);
  const awayPMOut = Number(awayProf.playmaking_impact || 0);
  const playmakingUnder = (homePMOut + awayPMOut) * 0.20;

  const totalsAdjustment = rimOver - shootingUnder - b2bUnder - restUnder - playmakingUnder;
  const adjustedExpected = Number((baseExpected + totalsAdjustment).toFixed(1));

  let totalsDirection    = null;
  let totalsEdgePts      = 0;
  let totalsSignalStrength = 0;
  let totalsEV           = 0;
  let totalsReasons      = [];

  if (avgTotal > 0) {
    totalsEdgePts = adjustedExpected - avgTotal;
    totalsDirection = totalsEdgePts > 0 ? 'Over' : 'Under';
    totalsSignalStrength = Number(Math.abs(totalsEdgePts).toFixed(1));

    // Reasons list for transparency
    if (shootingUnder > 0)    totalsReasons.push(`Shooters out -${shootingUnder.toFixed(1)}`);
    if (rimOver > 0)          totalsReasons.push(`Rim out +${rimOver.toFixed(1)}`);
    if (b2bUnder > 0)         totalsReasons.push(`B2B -${b2bUnder.toFixed(1)}`);
    if (restUnder > 0)        totalsReasons.push(`Short rest -${restUnder.toFixed(1)}`);
    if (playmakingUnder > 0)  totalsReasons.push(`PG out -${playmakingUnder.toFixed(1)}`);

    // EV approximation (typical -110 / 1.91 odds for totals)
    const totalsOdds = 1.91;
    // Simple probability estimate based on signal strength
    const totalsProb = totalsSignalStrength >= 6 ? 0.60 :
                       totalsSignalStrength >= 4 ? 0.57 :
                       totalsSignalStrength >= 2 ? 0.54 : 0.51;
    totalsEV = Number((totalsProb * totalsOdds - 1).toFixed(4));
  }

  // H2H total reference
  const h2hAvgTotal = h2h?.avg_game_total || null;

  return {
    json: {
      ...j,
      model_home_prob: Number(modelHomeProb.toFixed(4)),
      model_away_prob: Number(modelAwayProb.toFixed(4)),
      ev_home:         Number(evHome.toFixed(4)),
      ev_away:         Number(evAway.toFixed(4)),
      value_side:      valueSide,
      value_ev:        Number(valueEV.toFixed(4)),
      value_odds:      valueOdds,
      market_correction: {
        raw_edge:         Number(rawEdge.toFixed(4)),
        clamped_edge:     Number(clampedEdge.toFixed(4)),
        max_deviation:    maxDeviation,
        has_strong_factor: hasStrongFactor
      },
      totals_analysis: {
        avg_total:        avgTotal,
        base_expected:    Number(baseExpected.toFixed(1)),
        expected_total:   adjustedExpected,
        totals_edge:      Number(totalsEdgePts.toFixed(1)),
        direction:        totalsDirection,
        signal_strength:  totalsSignalStrength,
        shooting_under:   Number(shootingUnder.toFixed(1)),
        rim_over:         Number(rimOver.toFixed(1)),
        b2b_under:        b2bUnder,
        rest_under:       restUnder,
        playmaking_under: Number(playmakingUnder.toFixed(1)),
        totals_ev:        totalsEV,
        reasons:          totalsReasons,
        h2h_avg_total:    h2hAvgTotal
      },
      feature_breakdown: {
        market_base:    Number(marketBase.toFixed(4)),
        form_edge:      Number(formEdge.toFixed(4)),
        fg_edge:        Number(fgEdge.toFixed(4)),
        injury_edge:    Number(injuryEdge.toFixed(4)),
        net_rating_edge: Number(netRatingEdge.toFixed(4)),
        streak_edge:    Number(streakEdge.toFixed(4)),
        b2b_edge:       Number(b2bEdge.toFixed(4)),
        h2h_edge:       Number(h2hEdge.toFixed(4)),
        momentum_edge:  Number(momentumEdge.toFixed(4)),
        home_momentum:  `${homeMomentum}/2`,
        away_momentum:  `${awayMomentum}/2`
      }
    }
  };
});

return $input.all().map(item => {
  const j = item.json;

  let adjustedValueSide = j.value_side;
  let adjustedValueEV   = Number(j.value_ev || 0);
  let confidence        = "Niedrig";

  const odds        = Number(j.value_odds || 0);
  const homeProb    = Number(j.model_home_prob || 0);
  const awayProb    = Number(j.model_away_prob || 0);
  const selectedProb = adjustedValueSide === j.home_team ? homeProb :
                       adjustedValueSide === j.away_team ? awayProb : 0;

  const homeInjScore = Number(j.home_injuries_structured?.injury_impact_score || 0);
  const awayInjScore = Number(j.away_injuries_structured?.injury_impact_score || 0);
  const injuryGap    = Math.abs(homeInjScore - awayInjScore);

  const marketProb  = adjustedValueSide === j.home_team
    ? Number(j.market_home_prob_novig || 0)
    : Number(j.market_away_prob_novig || 0);
  const divergence  = Math.abs(selectedProb - marketProb);
  const probGap     = selectedProb - marketProb;

  // ===== MONEYLINE GUARDRAILS =====

  // 1. Odds zu hoch → skip
  if (odds >= 8.0) {
    adjustedValueSide = "SKIP"; adjustedValueEV = 0;
  }
  // 2. Hohe Odds nur mit starkem Edge
  if (odds >= 5.0 && adjustedValueEV < 0.15) {
    adjustedValueSide = "SKIP"; adjustedValueEV = 0;
  }
  // 3. Prob zu niedrig
  if (selectedProb < 0.38) {
    adjustedValueSide = "SKIP"; adjustedValueEV = 0;
  }
  // 4. Große Marktabweichung ohne klaren Grund → skip
  if (divergence > 0.15 && adjustedValueEV < 0.15) {
    adjustedValueSide = "SKIP"; adjustedValueEV = 0;
  }
  // 5. B2B: nur bei echtem Edge
  const selectedIsHome = adjustedValueSide === j.home_team;
  const selectedB2B = selectedIsHome
    ? j.home_stats?.back_to_back
    : j.away_stats?.back_to_back;
  if (selectedB2B && adjustedValueEV < 0.12) {
    adjustedValueSide = "SKIP"; adjustedValueEV = 0;
  }

  // ===== KONFIDENZ-KLASSIFIKATION (Punkt 9) =====
  // Klare, objektive Regeln basierend auf EV, Odds, Prob, Divergenz, ProbGap
  if (adjustedValueSide !== "SKIP") {
    if (
      adjustedValueEV >= 0.18 &&
      odds <= 3.5 &&
      selectedProb >= 0.62 &&
      divergence <= 0.18 &&
      probGap >= 0.06
    ) {
      confidence = "Hoch";
    } else if (
      adjustedValueEV >= 0.10 &&
      odds <= 5.0 &&
      selectedProb >= 0.50 &&
      divergence <= 0.25 &&
      probGap >= 0.05
    ) {
      confidence = "Mittel";
    } else {
      confidence = "Niedrig";
    }

    // Niedrig-Confidence → ausfiltern
    if (confidence === "Niedrig") {
      adjustedValueSide = "SKIP";
      adjustedValueEV   = 0;
    }
  }

  // ===== TOTALS PICK (Punkt 6 + 7) =====
  const ta = j.totals_analysis || {};
  let totalsPickDirection  = null;
  let totalsPickConfidence = "Niedrig";
  const totalsPickEV       = Number(ta.totals_ev || 0);
  const strength           = Number(ta.signal_strength || 0);

  if (ta.direction && ta.avg_total > 0) {
    // Guardrails: signal muss stark genug sein
    if (strength >= 6 && totalsPickEV >= 0.04) {
      totalsPickConfidence = "Hoch";
      totalsPickDirection  = ta.direction;
    } else if (strength >= 3.5 && totalsPickEV >= 0.02) {
      totalsPickConfidence = "Mittel";
      totalsPickDirection  = ta.direction;
    }
    // Schwache Signale ignorieren
    if (strength < 2.5) totalsPickDirection = null;
  }

  return {
    json: {
      ...j,
      value_side:  adjustedValueSide,
      value_ev:    Number(adjustedValueEV.toFixed(4)),
      confidence,
      totals_pick: {
        direction:       totalsPickDirection,
        confidence:      totalsPickConfidence,
        ev:              totalsPickEV,
        line:            ta.avg_total,
        expected:        ta.expected_total,
        signal_strength: strength,
        reasons:         ta.reasons || []
      },
      guardrails: {
        selected_prob: Number(selectedProb.toFixed(4)),
        market_prob:   Number(marketProb.toFixed(4)),
        prob_gap:      Number(probGap.toFixed(4)),
        divergence:    Number(divergence.toFixed(4)),
        injury_gap:    Number(injuryGap.toFixed(2)),
        odds_checked:  odds
      }
    }
  };
});

